/**
 * @param {string} uid
 * @returns {nsIAbCard}
 */
getCard(uid) {
  const card = new lazy.AddrBookCard();
  card.directoryUID = this.UID;
  card._uid = uid;
  card._properties = this.loadCardProperties(uid);
  card._isGoogleCardDAV = this._isGoogleCardDAV;
  return card.QueryInterface(Ci.nsIAbCard);
}
